void dfsIterative(int s) {
stack<int> st;
st.push(s);
while (!st.empty()) {
int u = st.top();
st.pop();
if (vis[u]) continue; // may have been pushed several times
vis[u] = true;
for (int v : adj[u])
if (!vis[v])
